// Core tests: the 7 literal core cases from fixtures.json (expected values
// taken verbatim from the file, never generated by the product), plus
// hand-derived boundary, validation, and BigInt-growth cases. The SPEC's
// own rules are the oracle; every expected value below was computed by hand.

import assert from "node:assert/strict";
import test from "node:test";
import { DEFAULTS, run } from "../public/js/core/retry.mjs";
import fixtures from "../../../docs/specs/retry-budget/fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = {
  budget: "100",
  timeout: "10",
  attemptLimit: "4",
  initialDelay: "50",
  factor: "3",
  maxDelay: "20",
};

test("cap smaller than initial delay applies from the second attempt", () => {
  assert.deepEqual(run(base), {
    ok: true,
    result: {
      attempts: [
        { number: 1, delayMs: 0, startMs: 0, endMs: 10 },
        { number: 2, delayMs: 20, startMs: 30, endMs: 40 },
        { number: 3, delayMs: 20, startMs: 60, endMs: 70 },
        { number: 4, delayMs: 20, startMs: 90, endMs: 100 },
      ],
      unspentMs: 0,
      nextRejected: null,
    },
  });
});

test("first attempt ending one millisecond past the budget is rejected", () => {
  assert.deepEqual(
    run({ budget: "5", timeout: "5", attemptLimit: "2", initialDelay: "1", factor: "2", maxDelay: "9" }),
    {
      ok: true,
      result: {
        attempts: [{ number: 1, delayMs: 0, startMs: 0, endMs: 5 }],
        unspentMs: 0,
        nextRejected: { number: 2, startMs: 6, endMs: 11 },
      },
    },
  );
});

test("attemptLimit 16 is accepted and fills exactly", () => {
  const result = run({
    budget: "16",
    timeout: "1",
    attemptLimit: "16",
    initialDelay: "0",
    factor: "1",
    maxDelay: "0",
  });
  assert.equal(result.ok, true);
  assert.equal(result.result.attempts.length, 16);
  assert.deepEqual(result.result.attempts[15], { number: 16, delayMs: 0, startMs: 15, endMs: 16 });
  assert.equal(result.result.unspentMs, 0);
  assert.equal(result.result.nextRejected, null);
});

test("uncapped exponential growth is computed exactly (BigInt path)", () => {
  const result = run({
    budget: "86400000",
    timeout: "1",
    attemptLimit: "16",
    initialDelay: "599999",
    factor: "8",
    maxDelay: "600000",
  });
  assert.equal(result.ok, true);
  assert.deepEqual(result.result.attempts[0], { number: 1, delayMs: 0, startMs: 0, endMs: 1 });
  assert.deepEqual(result.result.attempts[1], { number: 2, delayMs: 599999, startMs: 600000, endMs: 600001 });
  assert.deepEqual(result.result.attempts[2], { number: 3, delayMs: 600000, startMs: 1200001, endMs: 1200002 });
  assert.deepEqual(result.result.attempts[15], { number: 16, delayMs: 600000, startMs: 9000014, endMs: 9000015 });
  assert.equal(result.result.unspentMs, 77399985);
  assert.equal(result.result.nextRejected, null);
});

test("defaults produce four fitting attempts and a first rejection at 5", () => {
  assert.deepEqual(run(DEFAULTS), {
    ok: true,
    result: {
      attempts: [
        { number: 1, delayMs: 0, startMs: 0, endMs: 1500 },
        { number: 2, delayMs: 500, startMs: 2000, endMs: 3500 },
        { number: 3, delayMs: 1000, startMs: 4500, endMs: 6000 },
        { number: 4, delayMs: 2000, startMs: 8000, endMs: 9500 },
      ],
      unspentMs: 500,
      nextRejected: { number: 5, startMs: 11500, endMs: 13000 },
    },
  });
});

test("budget at its legal maximum is accepted", () => {
  const result = run({
    budget: "86400000",
    timeout: "600000",
    attemptLimit: "1",
    initialDelay: "0",
    factor: "1",
    maxDelay: "0",
  });
  assert.deepEqual(result, {
    ok: true,
    result: {
      attempts: [{ number: 1, delayMs: 0, startMs: 0, endMs: 600000 }],
      unspentMs: 85800000,
      nextRejected: null,
    },
  });
});

const errorCases = [
  ["budget over range", { ...base, budget: "86400001" }, { code: "RANGE", field: "budget", row: null }],
  ["timeout zero", { ...base, timeout: "0" }, { code: "RANGE", field: "timeout", row: null }],
  ["timeout over range", { ...base, timeout: "600001" }, { code: "RANGE", field: "timeout", row: null }],
  ["attemptLimit zero", { ...base, attemptLimit: "0" }, { code: "RANGE", field: "attemptLimit", row: null }],
  ["initialDelay over range", { ...base, initialDelay: "600001" }, { code: "RANGE", field: "initialDelay", row: null }],
  ["factor zero", { ...base, factor: "0" }, { code: "RANGE", field: "factor", row: null }],
  ["factor nine", { ...base, factor: "9" }, { code: "RANGE", field: "factor", row: null }],
  ["maxDelay over range", { ...base, maxDelay: "600001" }, { code: "RANGE", field: "maxDelay", row: null }],
  ["double zero", { ...base, budget: "00" }, { code: "INTEGER_FORMAT", field: "budget", row: null }],
  ["leading zero", { ...base, budget: "01" }, { code: "INTEGER_FORMAT", field: "budget", row: null }],
  ["leading space", { ...base, budget: " 5" }, { code: "INTEGER_FORMAT", field: "budget", row: null }],
  ["trailing space", { ...base, budget: "5 " }, { code: "INTEGER_FORMAT", field: "budget", row: null }],
  ["plus sign", { ...base, budget: "+5" }, { code: "INTEGER_FORMAT", field: "budget", row: null }],
  ["minus sign", { ...base, budget: "-5" }, { code: "INTEGER_FORMAT", field: "budget", row: null }],
  ["decimal", { ...base, budget: "5.0" }, { code: "INTEGER_FORMAT", field: "budget", row: null }],
  ["exponent", { ...base, budget: "1e3" }, { code: "INTEGER_FORMAT", field: "budget", row: null }],
  ["empty", { ...base, budget: "" }, { code: "EMPTY", field: "budget", row: null }],
  ["nine units", { ...base, budget: "123456789" }, { code: "INPUT_LIMIT", field: "budget", row: null }],
  ["lone high surrogate", { ...base, budget: "\uD800" }, { code: "UNICODE", field: "budget", row: null }],
  ["lone low surrogate", { ...base, budget: "\uDC00" }, { code: "UNICODE", field: "budget", row: null }],
  [
    "valid surrogate pair is not a digit",
    { ...base, budget: "\uD83D\uDE00" },
    { code: "INTEGER_FORMAT", field: "budget", row: null },
  ],
  [
    "capacity beats surrogate (nine units incl. lone surrogate)",
    { ...base, budget: "\uD80012345678" },
    { code: "INPUT_LIMIT", field: "budget", row: null },
  ],
];
for (const [name, input, error] of errorCases) {
  test(`validation: ${name}`, () => {
    assert.deepEqual(run(input), { ok: false, error });
  });
}

test("validation order follows the SPEC field order", () => {
  assert.deepEqual(run({ ...base, budget: "abc", timeout: "0" }), {
    ok: false,
    error: { code: "INTEGER_FORMAT", field: "budget", row: null },
  });
  assert.deepEqual(run({ ...base, budget: "123456789", timeout: "abc" }), {
    ok: false,
    error: { code: "INPUT_LIMIT", field: "budget", row: null },
  });
  assert.deepEqual(run({ ...base, timeout: "abc", attemptLimit: "17" }), {
    ok: false,
    error: { code: "INTEGER_FORMAT", field: "timeout", row: null },
  });
});

test("schema: missing, extra, mistyped, and accessor inputs", () => {
  const { budget, ...missing } = base;
  assert.deepEqual(run(missing), { ok: false, error: { code: "SCHEMA", field: null, row: null } });
  assert.deepEqual(run({ ...base, extra: "1" }), {
    ok: false,
    error: { code: "SCHEMA", field: null, row: null },
  });
  assert.deepEqual(run({ ...base, budget: 5 }), {
    ok: false,
    error: { code: "SCHEMA", field: null, row: null },
  });
  assert.deepEqual(run({ ...base, budget: undefined }), {
    ok: false,
    error: { code: "SCHEMA", field: null, row: null },
  });
  assert.deepEqual(run(null), { ok: false, error: { code: "SCHEMA", field: null, row: null } });
  assert.deepEqual(run([base]), { ok: false, error: { code: "SCHEMA", field: null, row: null } });
  const throwing = { ...base };
  Object.defineProperty(throwing, "budget", {
    get() {
      throw new Error("boom");
    },
  });
  assert.deepEqual(run(throwing), { ok: false, error: { code: "SCHEMA", field: null, row: null } });
});

test("accepted ends never exceed the budget; removing the cap never shortens a delay", () => {
  const capped = run(base);
  assert.equal(capped.ok, true);
  for (const attempt of capped.result.attempts) {
    assert.ok(attempt.endMs <= 100, `attempt ${attempt.number} ends past budget`);
  }
  const uncapped = run({ ...base, maxDelay: "600000", budget: "86400000" });
  assert.equal(uncapped.ok, true);
  for (let i = 1; i < uncapped.result.attempts.length; i += 1) {
    assert.ok(
      uncapped.result.attempts[i].delayMs >= capped.result.attempts[i]?.delayMs ?? 0,
      "uncapped delay must not be shorter",
    );
  }
});
